package com.oldschoolnetwork.core.lite;
import android.app.Activity;import android.os.Bundle;import android.view.View;import android.widget.*;import com.oldschoolnetwork.lite.Api;import org.json.*;
public final class RecoveryActivity extends Activity {
 public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.recovery);final Spinner issue=(Spinner)findViewById(R.id.issue);issue.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Account access","Password","Verification"}));findViewById(R.id.send).setOnClickListener(new View.OnClickListener(){public void onClick(View v){JSONObject request=new JSONObject();try{request.put("login",((EditText)findViewById(R.id.login)).getText().toString()).put("contact_email",((EditText)findViewById(R.id.email)).getText().toString()).put("message",((EditText)findViewById(R.id.description)).getText().toString()).put("issue",new String[]{"account","password","verification"}[issue.getSelectedItemPosition()]);}catch(Exception e){return;}findViewById(R.id.send).setEnabled(false);Api.call(RecoveryActivity.this,"account_recovery_request",request,false,new Api.Callback(){public void complete(JSONObject r,String error){if(isFinishing())return;findViewById(R.id.send).setEnabled(error!=null);((TextView)findViewById(R.id.status)).setText(error==null?r.optString("message"):error);}});}});}
}
